import { TOWN_DATA } from './town-data';

/**
 * Cerulean City as the game draws it — the map every hero walks.
 *
 * Everything here is generated by scripts/bake-pokemon/town.py from the
 * FireRed decompilation's own map data (`town-data.ts`): which blocks can be
 * walked on, the doors, where a crowd stands in front of each building, and
 * the two baked images (`ground.png` below the sprites, `overhead.png` above
 * them). Nothing is placed or routed by hand on the client.
 *
 * Coordinates come in two kinds: TILES (one 16px FireRed block, the unit the
 * game moves in) and world PIXELS (a tile is 32px — the art is baked at x2).
 * A hero's position on a tile is its FEET: horizontally centred, just above
 * the tile's bottom edge, the way an overworld sprite stands in the game.
 */

export const TILE = 32;

export interface Point {
  x: number;
  y: number;
}

export type Tile = readonly [number, number];

export interface TownBuilding {
  readonly label: string;
  /** Footprint in tiles: [x, y, w, h] — the click target and label anchor. */
  readonly rect: readonly [number, number, number, number];
  /** Warp tiles: where the building's doors are. Empty for open-air spots. */
  readonly doors: readonly Tile[];
  /** Where heroes stand, best first: the doorstep, then outward. */
  readonly slots: readonly Tile[];
  /** Open-door frames laid over a door while someone is inside. */
  readonly doorOverlays: ReadonlyArray<{ readonly key: string; readonly tile: Tile }>;
  /** Name the place on its own roof rather than above it — for a building
   * whose label band would land on a neighbour. */
  readonly labelInside: boolean;
  /** Nugget Bridge only: where the Pokémon facing the trainers stand. */
  readonly fighters?: readonly Tile[];
}

export const TOWN_NAME: string = TOWN_DATA.name;
export const TOWN_COLS: number = TOWN_DATA.cols;
export const TOWN_ROWS: number = TOWN_DATA.rows;
export const WORLD_WIDTH = TOWN_COLS * TILE;
export const WORLD_HEIGHT = TOWN_ROWS * TILE;

export const TOWN_BUILDINGS: Readonly<Record<string, TownBuilding>> = TOWN_DATA.buildings;

/** Where heroes enter town: the west edge, along Route 4 from Mt. Moon. */
export const SPAWN_TILE: Tile = TOWN_DATA.spawn as unknown as Tile;

/** The rect, in tiles, the camera opens on. */
export const VIEW_RECT = TOWN_DATA.view;

const WALK: readonly string[] = TOWN_DATA.walk;

export function isWalkable(tx: number, ty: number): boolean {
  return WALK[ty]?.[tx] === '.';
}

/** World position of a hero's feet standing on a tile. */
export function footOf(tile: Tile): Point {
  return { x: tile[0] * TILE + TILE / 2, y: tile[1] * TILE + TILE - 2 };
}

/** The tile a world point (a hero's feet) is on. */
export function tileAt(p: Point): Tile {
  return [Math.floor(p.x / TILE), Math.floor(p.y / TILE)];
}

/** A tile's rect in world pixels. */
export function tileRectToWorld(rect: readonly [number, number, number, number]): {
  x: number; y: number; w: number; h: number;
} {
  return { x: rect[0] * TILE, y: rect[1] * TILE, w: rect[2] * TILE, h: rect[3] * TILE };
}
